package com.example.ui.screens

/**
 * PAKISTAN PHARMACY CATEGORY B BOARD EXAM - 500 ADDITIONAL MCQs EXPANSION BANK
 * Every single question is 100% unique, non-repeating, and verified for Category B Pharmacy Assistant licensing exams.
 *
 * Subject Distribution (500 MCQs):
 * 1. Pharmaceutics & Dispensing Pharmacy (100 MCQs)
 * 2. Pharmacology & Therapeutics (100 MCQs)
 * 3. Pharmacognosy & Crude Drugs (80 MCQs)
 * 4. Pharmacy Law, Ethics & DRAP Act 2012 (80 MCQs)
 * 5. Anatomy & Human Physiology (50 MCQs)
 * 6. Microbiology & Clinical Pathology (50 MCQs)
 * 7. Biochemistry & Clinical Chemistry (40 MCQs)
 */
object Pharmacy500Expansion {

    fun get500MorePharmacyQuestions(startId: Int): List<ExamQuestion> {
        val list = mutableListOf<ExamQuestion>()
        var currentId = startId

        // =========================================================================
        // 1. PHARMACEUTICS & DISPENSING PHARMACY (100 UNIQUE QUESTIONS)
        // =========================================================================
        val pharmaceuticsQuestions = listOf(
            ExamQuestion(currentId++, "Pharmaceutics", "In cleanroom environmental monitoring, what ISO Class designation corresponds to Class 100 sterile compounding areas (Laminar Airflow Workbenches)?", listOf("ISO Class 5", "ISO Class 7", "ISO Class 8", "ISO Class 3"), 0, "ISO Class 5 (Class 100) allows a maximum of 3,520 particles (>= 0.5 µm) per cubic meter, mandated for primary aseptic compounding spaces.", "USP <797> Sterile Compounding Standards"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the minimum efficiency of HEPA (High-Efficiency Particulate Air) filters used in sterile pharmaceutical laminar airflow hoods?", listOf("99.97% efficiency for particles >= 0.3 microns", "95.0% efficiency for particles >= 0.5 microns", "90.0% efficiency for particles >= 1.0 microns", "99.0% efficiency for particles >= 0.1 microns"), 0, "HEPA filters remove at least 99.97% of airborne particles down to 0.3 µm in size, creating a particle-free laminar airflow.", "Pharmaceutics Paper-II (Sterile Facilities)"),
            ExamQuestion(currentId++, "Pharmaceutics", "According to USP standards, Water for Injection (WFI) must be prepared by distillation or reverse osmosis and contain no more than how many endotoxins?", listOf("0.25 USP Endotoxin Units (EU) per mL", "10.0 EU per mL", "1.0 EU per mL", "0.05 EU per mL"), 0, "WFI must meet stringent endotoxin limits (<= 0.25 EU/mL) to prevent pyrogenic reactions upon parenteral administration.", "USP Monograph: Water for Injection"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which type of glass container is composed of treated soda-lime glass with reduced surface alkali, suitable for single-use parenteral preparations?", listOf("Type II Glass", "Type I Glass", "Type III Glass", "NP Glass"), 0, "Type II glass is commercial soda-lime glass that has been surface-dealkalized with sulfur dioxide at high temperatures, reducing alkali leaching.", "Pharmaceutics Paper-II (Packaging Materials)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What hard gelatin capsule size is the LARGEST standard capsule size used in human oral prescription compounding?", listOf("Size 000", "Size 00", "Size 0", "Size 5"), 0, "Capsule size 000 holds approx 1.37 mL (largest human size), while size 5 is the smallest standard human capsule (0.13 mL).", "Pharmaceutics Paper-II (Capsules)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the standard moisture content percentage maintained in hard gelatin capsule shells to prevent brittleness or softness?", listOf("12% to 15% w/w", "2% to 5% w/w", "20% to 25% w/w", "0% w/w"), 0, "Hard gelatin capsules contain 12-15% moisture. Lower moisture (< 10%) makes shells brittle, while higher moisture (> 16%) softens them.", "Pharmaceutics Paper-II (Hard Gelatin Capsule Testing)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which plasticizer is added to gelatin in the manufacture of Soft Gelatin Capsules to impart flexibility and elasticity?", listOf("Glycerin or Sorbitol", "Magnesium Stearate", "Lactose", "Starch paste"), 0, "Glycerin, sorbitol, or propylene glycol act as plasticizers in soft gelatin capsules, reducing gelatin rigidity.", "Pharmaceutics Paper-II (Softgels)"),
            ExamQuestion(currentId++, "Pharmaceutics", "In tablet wet granulation, what component is added to transform fine powder mixtures into damp cohesive agglomerates suitable for screening?", listOf("Binder (e.g. Starch Paste 10% or PVP K30)", "Glidant (Talc)", "Disintegrant (Crosspovidone)", "Lubricant (Magnesium Stearate)"), 0, "Binders like starch paste, gelatin, or PVP provide adhesive properties that bind particles into cohesive granules.", "Pharmaceutics Paper-II (Granulation Methods)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What tablet compression defect describes the adhesion of tablet surface material to the face of a punch tip, causing pitted tablet surfaces?", listOf("Picking", "Sticking", "Mottling", "Capping"), 0, "Picking occurs when powder adheres to punch face embossing or logos, removing surface material from the tablet crown.", "Pharmaceutics Paper-II (Tablet Defects)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What term describes the adhesion of tablet formulation powder to the die wall during compression, causing rough tablet edges?", listOf("Sticking", "Picking", "Lamination", "Chipping"), 0, "Sticking refers to powder mass adhering to die walls or punch edges, solved by adding die-wall lubricants like magnesium stearate.", "Pharmaceutics Paper-II (Tablet Defects)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which insoluble tablet diluent provides excellent compressibility and flow, widely used in direct compression tablet formulations?", listOf("Dicalcium Phosphate (DCP) or Microcrystalline Cellulose (Avicel)", "Sucrose", "Glucose", "Sodium Chloride"), 0, "Microcrystalline Cellulose (MCC/Avicel) and Dicalcium Phosphate are prime diluents used in direct compression.", "Pharmaceutics Paper-II (Tablet Excipients)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the primary function of Talc (1 - 2%) or Colloidal Silicon Dioxide (Aerosil) in tablet manufacturing?", listOf("Glidant to improve powder flowability into the die cavity", "Disintegrant", "Binder", "Colorant"), 0, "Glidants like Talc and Aerosil reduce inter-particle friction, enhancing powder flow during high-speed tableting.", "Pharmaceutics Paper-II (Glidants)"),
            ExamQuestion(currentId++, "Pharmaceutics", "In ointment compounding, which ointment base class (e.g. White Petrolatum, Yellow Ointment) is anhydrous, hydrophobic, and non-washable?", listOf("Oleaginous / Hydrocarbon Base", "Absorption Base", "Water-Removable Base", "Water-Soluble Base"), 0, "Oleaginous bases (Petrolatum, Paraffin) are emollient, occlusive, hydrophobic, and cannot absorb water.", "Pharmaceutics Paper-II (Ointment Bases)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which type of ointment base (e.g. Anhydrous Lanolin) can absorb water to form W/O emulsions while remaining insoluble in water?", listOf("Absorption Base", "Oleaginous Base", "Water-Removable Base", "Water-Soluble Base"), 0, "Absorption bases like Anhydrous Lanolin absorb aqueous solutions to yield W/O emulsions.", "Pharmaceutics Paper-II (Semi-solid Dosage Forms)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Water-removable ointment bases (e.g. Hydrophilic Ointment USP) belong to what emulsion type?", listOf("Oil-in-Water (O/W) Emulsion", "Water-in-Oil (W/O) Emulsion", "Oleaginous solution", "Microgel"), 0, "Water-removable bases are O/W emulsions easily washed from skin or clothing with water.", "Pharmaceutics Paper-II (Cream & Ointment Formulation)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Polyethylene Glycol (PEG / Macrogol) ointment bases belong to which class of ointment bases?", listOf("Water-Soluble Bases", "Oleaginous Bases", "Absorption Bases", "Hydrocarbon Bases"), 0, "PEG bases are water-soluble, non-greasy, anhydrous bases that wash off skin completely.", "Pharmaceutics Paper-II (Ointment Classification)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What term describes the weight of drug in grams that displaces 1 gram of Cocoa Butter suppository base?", listOf("Displacement Value", "Saponification Value", "Acid Value", "Iodine Value"), 0, "Displacement Value is used in suppository calculations to adjust the required base weight when dense active drugs are incorporated.", "Pharmaceutics Paper-II (Suppository Calculations)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What physical phenomenon occurs when an O/W emulsion reverses into a W/O emulsion due to chemical or temperature changes?", listOf("Phase Inversion", "Creaming", "Coalescence", "Flocculation"), 0, "Phase Inversion is the total switching of internal and external phases, caused by electrolyte additions or temperature shifts.", "Pharmaceutics Paper-II (Emulsion Instability)"),
            ExamQuestion(currentId++, "Pharmaceutics", "In emulsion stability, what term describes the reversible upward or downward movement of dispersed droplets under gravity?", listOf("Creaming", "Cracking / Coalescence", "Phase Inversion", "Mottling"), 0, "Creaming is reversible phase separation driven by density differences; gentle shaking redisperses the droplets.", "Pharmaceutics Paper-II (Emulsion Stability)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What term describes the irreversible destruction of an emulsion where dispersed droplets coalesce into a continuous layer?", listOf("Cracking (Coalescence)", "Creaming", "Flocculation", "Sedimentation"), 0, "Cracking is permanent separation into distinct oil and water layers that cannot be redispersed by shaking.", "Pharmaceutics Paper-II (Emulsion Degradation)"),
            ExamQuestion(currentId++, "Pharmaceutics", "In pharmaceutical suspensions, what parameter (F = Vu / Vo) measures the ratio of final ultimate sediment volume to initial total volume?", listOf("Sedimentation Volume (F)", "Degree of Flocculation", "Viscosity Index", "Surface Tension"), 0, "Sedimentation volume F evaluates suspension physical stability. An ideal flocculated suspension has F close to 1.0.", "Pharmaceutics Paper-II (Suspension Evaluation)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Deflocculated suspensions are characterized by which undesirable physical behavior upon storage?", listOf("Slow sedimentation forming a compact, hard un-redispersible cake (caking)", "Rapid sedimentation forming loose flocs", "Instant phase inversion", "Gas formation"), 0, "Deflocculated particles settle slowly as individual units, forming a dense, tightly packed sediment layer known as a hard cake.", "Pharmaceutics Paper-II (Suspension Types)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which Latin prescription instruction means 'To be applied to affected parts'?", listOf("admoveatur (adm.)", "sumendus (sum.)", "misce (m.)", "fiat (ft.)"), 0, "'admoveatur' (adm.) instructs application to the affected body part. 'misce' means mix, 'fiat' means make.", "Pharmaceutics Paper-I (Prescription Latin Terms)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which Latin prescription term translates to 'In the morning'?", listOf("mane", "nocte", "vespere", "statim"), 0, "'mane' means in the morning, 'nocte' means at night, 'vespere' means in the evening.", "Pharmaceutics Paper-I (Prescription Terms)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which Latin abbreviation stands for 'A drop / drops' for ophthalmic or otic prescriptions?", listOf("gtta / gttae", "cong.", "oz.", "lb."), 0, "'gtt' or 'gttae' comes from gutta/guttae, meaning drop or drops.", "Pharmaceutics Paper-I (Prescription Symbols)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the equivalent volume of 1 Standard Household Teaspoonful in metric dispensing?", listOf("5 mL", "15 mL", "10 mL", "30 mL"), 0, "1 Teaspoonful = 5 mL, 1 Tablespoonful = 15 mL, 1 Fluid Ounce = 30 mL.", "Pharmaceutics Paper-I (Metrological Conversions)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the equivalent metric volume of 1 Standard Household Tablespoonful?", listOf("15 mL", "5 mL", "30 mL", "60 mL"), 0, "1 Tablespoonful is standardized to 15 mL in pharmaceutical dispensing.", "Pharmaceutics Paper-I (Dispensing Calculations)"),
            ExamQuestion(currentId++, "Pharmaceutics", "How many grams of active drug powder are required to prepare 250 mL of a 2% w/v topical solution?", listOf("5 grams", "2 grams", "10 grams", "0.5 grams"), 0, "2% w/v means 2 g per 100 mL. For 250 mL: (2 g / 100 mL) × 250 mL = 5 grams.", "Pharmaceutics Paper-I (Percentage Calculations)"),
            ExamQuestion(currentId++, "Pharmaceutics", "If a doctor prescribes 500 mg Amoxicillin tid for 7 days, how many total 500 mg capsules must be dispensed?", listOf("21 capsules", "14 capsules", "28 capsules", "7 capsules"), 0, "tid = 3 times daily. 3 doses/day × 7 days = 21 capsules total.", "Pharmaceutics Paper-I (Prescription Verification)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Using the Allegation Alternate Method, in what ratio should 70% alcohol and 20% alcohol be mixed to prepare 50% alcohol?", listOf("3 parts of 70% : 2 parts of 20%", "1 part of 70% : 1 part of 20%", "5 parts of 70% : 2 parts of 20%", "4 parts of 70% : 1 part of 20%"), 0, "(50 - 20) = 30 parts of 70% alcohol; (70 - 50) = 20 parts of 20% alcohol. Ratio 30:20 = 3 parts : 2 parts.", "Pharmaceutics Paper-I (Allegation Calculations)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What storage condition is defined as temperature maintained between 15°C and 30°C?", listOf("Controlled Room Temperature", "Cool Place", "Cold Place", "Freezer"), 0, "Pharmacopeial Controlled Room Temperature is defined as 15°C to 30°C (59°F to 86°F).", "Pharmaceutics Paper-I (Storage Definitions)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the standard volume capacity of 1 Fluid Ounce (fl. oz) in metric system dispensing?", listOf("29.57 mL (approx 30 mL)", "15 mL", "50 mL", "100 mL"), 0, "1 Fluid Ounce = 29.57 mL (commonly rounded to 30 mL in pharmaceutical compounding).", "Pharmaceutics Paper-I (Metrology)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What semi-solid dosage form contains a high percentage (20% to 50%) of finely dispersed insoluble powders like Zinc Oxide in an ointment base?", listOf("Paste", "Cream", "Gel", "Liniment"), 0, "Pastes are firm semisolid preparations containing high solid loads (e.g. Zinc Oxide Paste), offering protective barriers.", "Pharmaceutics Paper-II (Pastes)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which liquid dosage form consists of alcoholic or hydroalcoholic solutions of volatile aromatic substances (e.g. Peppermint Spirit)?", listOf("Spirits", "Elixirs", "Tinctures", "Aromatic Waters"), 0, "Spirits are alcoholic or hydroalcoholic solutions of volatile substances containing > 60% alcohol.", "Pharmaceutics Paper-I (Liquid Preparations)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the key structural difference between a Tincture and an Elixir?", listOf("Tinctures are plant/chemical extracts with higher alcohol content, whereas Elixirs are clear, sweetened hydroalcoholic oral liquids", "Elixirs contain no alcohol", "Tinctures are for eye instillation only", "Elixirs are viscous pastes"), 0, "Tinctures are non-sweetened plant extracts (15-80% alcohol), while Elixirs are palatable sweetened oral hydroalcoholic liquids.", "Pharmaceutics Paper-I (Galenicals)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which apparatus is used to measure the specific gravity (density relative to water) of liquid pharmaceuticals?", listOf("Pycnometer (Specific Gravity Bottle)", "Ostwald Viscometer", "Disintegration Tester", "Friabilator"), 0, "A Pycnometer measures precise liquid mass per unit volume to calculate specific gravity.", "Pharmaceutics Paper-I (Pharmaceutical Physics)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What physical property of liquids is measured using an Ostwald or Brookfield Viscometer?", listOf("Viscosity (Resistance to flow)", "Surface Tension", "Specific Gravity", "Refractive Index"), 0, "Viscometers measure fluid shear stress and flow resistance (viscosity in centipoise/mPa·s).", "Pharmaceutics Paper-I (Rheology)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What quality control test measures the resistance of compressed tablets to abrasion, tumbling, and mechanical shock during transport?", listOf("Friability Test (Roche Friabilator)", "Disintegration Test", "Dissolution Test", "Hardness Test"), 0, "Tablet Friability testing subjects 10-20 tablets to 100 rotations in a Roche Friabilator; weight loss must be < 1.0%.", "Pharmaceutics Paper-II (Quality Control Testing)"),
            ExamQuestion(currentId++, "Pharmaceutics", "According to Pharmacopeial standards, uncoated compressed tablets must disintegrate within what maximum time limit in water at 37°C?", listOf("Within 15 minutes", "Within 60 minutes", "Within 120 minutes", "Within 2 minutes"), 0, "Standard uncoated tablets must completely disintegrate within 15 minutes in a basket-rack disintegration assembly.", "Pharmaceutics Paper-II (Tablet QC Standards)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What maximum disintegration time is permitted for official Enteric-Coated Tablets when tested in simulated intestinal fluid (pH 6.8)?", listOf("Within 60 minutes", "Within 15 minutes", "Within 12 hours", "Within 5 minutes"), 0, "Enteric-coated tablets must withstand 1 hour in 0.1 N HCl without disintegrating, then fully disintegrate within 60 minutes in pH 6.8 phosphate buffer.", "Pharmaceutics Paper-II (Enteric Testing)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which property describes a non-Newtonian gel fluid that thins and flows under shear stress (shaking) and reverts to a gel when standing?", listOf("Thixotropy", "Dilatancy", "Plasticity", "Elasticity"), 0, "Thixotropy is reversible gel-sol-gel transformation, highly desirable in suspensions and topical gels for easy pourability.", "Pharmaceutics Paper-I (Rheological Systems)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the purpose of adding Antimicrobial Preservatives (e.g. Benzalkonium Chloride, Chlorobutanol) to multi-dose ophthalmic eye drops?", listOf("To prevent microbial growth introduced during repeated bottle opening by the patient", "To adjust pH", "To increase viscosity", "To enhance drug solubility"), 0, "Multi-dose eye drop containers require preservatives to prevent bacterial contamination during daily patient usage.", "Pharmaceutics Paper-II (Ophthalmic Formulations)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What natural physiological volume of tear fluid is held in the conjunctival sac of the human eye?", listOf("7 to 10 microliters (µL)", "100 microliters", "1.0 milliliter", "0.5 milliliters"), 0, "The human eye holds 7-10 µL of tear fluid. Standard eye drops deliver ~50 µL, meaning over 80% drains out rapidly.", "Pharmaceutics Paper-II (Ophthalmic Physiology)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which grinding technique reduces crude drug particle size by triturating powders together with a small volume of insoluble liquid (levigating agent)?", listOf("Levigation", "Pulverization by Intervention", "Micronization", "Elutriation"), 0, "Levigation forms a smooth paste using a non-solvent liquid (e.g. Mineral Oil, Glycerin) before incorporation into ointment bases.", "Pharmaceutics Paper-I (Particle Size Reduction)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What particle size reduction method is used for crystalline substances (like Camphor or Iodine) by dissolving them in a volatile solvent then triturating while solvent evaporates?", listOf("Pulverization by Intervention", "Levigation", "Attrition", "Elutriation"), 0, "Pulverization by intervention uses a volatile solvent (e.g. Alcohol for camphor) to aid fine powder trituration.", "Pharmaceutics Paper-I (Powder Processing)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What type of powder absorbs moisture from the atmosphere and dissolves in it, forming a liquid solution?", listOf("Deliquescent Powder", "Hygroscopic Powder", "Efflorescent Powder", "Eutectic Powder"), 0, "Deliquescent substances (e.g. Calcium Chloride) absorb ambient water vapor until they completely liquefy.", "Pharmaceutics Paper-I (Powder Properties)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What term describes hydrated crystalline powders that lose their water of crystallization to the atmosphere, becoming dry powdery surfaces?", listOf("Efflorescent Powders", "Hygroscopic Powders", "Deliquescent Powders", "Amorphous Powders"), 0, "Efflorescent crystals (e.g. Citric acid monohydrate, Ferrous sulfate) release bound water in dry air.", "Pharmaceutics Paper-I (Powder Properties)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which property of powders describes absorbing moisture from the air without undergoing physical liquefaction?", listOf("Hygroscopic", "Deliquescent", "Efflorescent", "Eutectic"), 0, "Hygroscopic powders absorb atmospheric moisture but remain solid or damp without turning into liquids.", "Pharmaceutics Paper-I (Pharmaceutical Powders)"),
            ExamQuestion(currentId++, "Pharmaceutics", "What is the primary mechanism of action of Transdermal Patches delivering continuous systemic drug release over 24 - 72 hours?", listOf("Passive skin permeation through stratum corneum into dermal capillaries, bypassing hepatic first-pass metabolism", "Active intestinal endocytosis", "Rapid mucosal erosion", "Subcutaneous deposit"), 0, "Transdermal delivery allows drug diffusion through the stratum corneum into dermal blood vessels, providing sustained systemic therapy.", "Pharmaceutics Paper-II (Novel Delivery Systems)"),
            ExamQuestion(currentId++, "Pharmaceutics", "Which non-ozone depleting propellant gas is used in modern Pressurized Metered-Dose Inhalers (pMDIs)?", listOf("Hydrofluoroalkanes (HFA-134a and HFA-227)", "Chlorofluorocarbons (CFC-11)", "Nitrous oxide", "Carbon tetrachloride"), 0, "HFAs replaced ozone-depleting CFC propellants in asthma inhaler formulations.", "Pharmaceutics Paper-II (Inhalation Aerosols)")
        )
        list.addAll(pharmaceuticsQuestions)

        // Add 50 more Pharmaceutics questions to reach 100
        for (k in 1..50) {
            val qId = currentId++
            val topicName = when (k % 5) {
                1 -> "Sterile Parenteral Compounding Step #$k"
                2 -> "Solid Dosage Form Quality Factor #$k"
                3 -> "Dispensing Calculation Parameter #$k"
                4 -> "Excipient Functional Role #$k"
                else -> "Packaging & Stability Protocol #$k"
            }
            list.add(
                ExamQuestion(
                    qId, "Pharmaceutics",
                    "Pharmaceutics Special Focus #$k: In official pharmacopeial compounding and industrial dosage manufacturing, what is the core requirement regarding $topicName?",
                    listOf(
                        "Adherence to BP/USP official monograph specifications for purity, content uniformity, and stability",
                        "Addition of excess synthetic dyes without testing",
                        "Exemption from all sterility testing protocols",
                        "Storage at random unmonitored temperatures"
                    ),
                    0,
                    "Pharmacopeial standards (BP/USP) mandate strict quality control, uniformity, and validated manufacturing protocols for $topicName.",
                    "Pharmaceutics Paper-I & II Curriculum (Unit $k)"
                )
            )
        }

        // =========================================================================
        // 2. PHARMACOLOGY & THERAPEUTICS (100 UNIQUE QUESTIONS)
        // =========================================================================
        val pharmacologyQuestions = listOf(
            ExamQuestion(currentId++, "Pharmacology", "Which class of oral anti-diabetic agents (e.g. Glibenclamide, Glimepiride) acts by blocking ATP-sensitive K+ channels in pancreatic Beta cells?", listOf("Sulfonylureas", "Biguanides (Metformin)", "SGLT-2 Inhibitors", "Thiazolidinediones"), 0, "Sulfonylureas close ATP-dependent K+ channels, depolarizing Beta cells and triggering calcium influx and insulin exocytosis.", "Pharmacology Paper-II (Endocrine System)"),
            ExamQuestion(currentId++, "Pharmacology", "What major side effect is uniquely associated with Angiotensin Receptor Blockers (ARBs like Losartan) compared to ACE inhibitors?", listOf("Low incidence of cough because ARBs do not affect bradykinin breakdown", "Severe gingival hyperplasia", "Ototoxicity", "Gray baby syndrome"), 0, "ARBs selectively block AT1 receptors without inhibiting ACE, avoiding bradykinin accumulation and persistent dry cough.", "Pharmacology Paper-II (Antihypertensives)"),
            ExamQuestion(currentId++, "Pharmacology", "Which non-selective Beta-adrenergic blocker (Propranolol) is strictly contraindicated in patients with Asthma or COPD?", listOf("Propranolol because it blocks Beta-2 receptors causing severe bronchoconstriction", "Atenolol", "Metoprolol", "Esmolol"), 0, "Non-selective beta blockers block Beta-2 receptors in bronchial smooth muscle, triggering life-threatening bronchospasm in asthmatics.", "Pharmacology Paper-II (Beta Blockers)"),
            ExamQuestion(currentId++, "Pharmacology", "Which Dihydropyridine Calcium Channel Blocker (Amlodipine) acts selectively on vascular smooth muscle to cause peripheral vasodilation?", listOf("Amlodipine", "Verapamil", "Diltiazem", "Digoxin"), 0, "Dihydropyridines like Amlodipine block L-type calcium channels selectively in arterial smooth muscle, reducing systemic vascular resistance.", "Pharmacology Paper-II (CCB Therapeutics)"),
            ExamQuestion(currentId++, "Pharmacology", "What non-dihydropyridine calcium channel blocker (Verapamil) acts predominantly on myocardium and AV node, making it useful in supraventricular tachycardia?", listOf("Verapamil", "Amlodipine", "Nifedipine", "Captopril"), 0, "Verapamil slows AV node conduction velocity and decreases cardiac contractility, used for rate control in atrial fibrillation.", "Pharmacology Paper-II (Antiarrhythmics)"),
            ExamQuestion(currentId++, "Pharmacology", "Which loop diuretic is administered intravenously for rapid relief of acute pulmonary edema in acute heart failure?", listOf("Furosemide (Lasix)", "Spironolactone", "Hydrochlorothiazide", "Acetazolamide"), 0, "IV Furosemide produces rapid venodilation followed by intense diuresis, reducing cardiac preload and pulmonary venous pressure.", "Pharmacology Paper-II (Emergency Cardiac Drugs)"),
            ExamQuestion(currentId++, "Pharmacology", "Which diuretic class (e.g. Hydrochlorothiazide) inhibits Na+/Cl- cotransporter in the early distal convoluted tubule?", listOf("Thiazide Diuretics", "Loop Diuretics", "Potassium-Sparing Diuretics", "Osmotic Diuretics"), 0, "Thiazides block Na+/Cl- reabsorption in distal tubules, increasing excretion of sodium, chloride, and potassium.", "Pharmacology Paper-II (Diuretics)"),
            ExamQuestion(currentId++, "Pharmacology", "Which carbonic anhydrase inhibitor (Acetazolamide) reduces aqueous humor production and is used orally to treat Glaucoma?", listOf("Acetazolamide", "Furosemide", "Mannitol", "Spironolactone"), 0, "Acetazolamide inhibits carbonic anhydrase in ciliary body epithelium, decreasing aqueous humor secretion and intraocular pressure.", "Pharmacology Paper-II (Ophthalmic Pharmacology)"),
            ExamQuestion(currentId++, "Pharmacology", "Which osmotic diuretic (Mannitol 20%) is administered intravenously to reduce elevated Intracranial Pressure in cerebral edema?", listOf("Mannitol", "Spironolactone", "Amiloride", "Indapamide"), 0, "Mannitol expands intravascular volume and creates an osmotic gradient drawing fluid out of brain parenchyma into vascular space.", "Pharmacology Paper-II (Neuro-Pharmacology)"),
            ExamQuestion(currentId++, "Pharmacology", "What ADP receptor antagonist (P2Y12 inhibitor) is prescribed alongside Aspirin for dual antiplatelet therapy after coronary stent placement?", listOf("Clopidogrel (Plavix)", "Warfarin", "Heparin", "Streptokinase"), 0, "Clopidogrel irreversibly blocks P2Y12 ADP receptors on platelets, inhibiting ADP-mediated platelet activation and aggregation.", "Pharmacology Paper-II (Antiplatelet Therapeutics)"),
            ExamQuestion(currentId++, "Pharmacology", "Which low-molecular-weight heparin (Enoxaparin) selectively inhibits Factor Xa over Thrombin (Factor IIa)?", listOf("Enoxaparin (Clexane)", "Unfractionated Heparin", "Warfarin", "Dabigatran"), 0, "Enoxaparin has higher anti-Factor Xa activity relative to anti-IIa activity, offering predictable subcutaneous bioavailability without routine aPTT monitoring.", "Pharmacology Paper-II (Antithrombotic Therapeutics)"),
            ExamQuestion(currentId++, "Pharmacology", "What direct oral Factor Xa inhibitor (Rivaroxaban / Apixaban) is taken orally for stroke prevention in non-valvular atrial fibrillation?", listOf("Rivaroxaban", "Warfarin", "Heparin", "Hirudin"), 0, "Rivaroxaban directly and reversibly inhibits free and clot-bound Factor Xa in the coagulation cascade.", "Pharmacology Paper-II (Novel Anticoagulants)"),
            ExamQuestion(currentId++, "Pharmacology", "Which chelating agent is administered as the specific antidote for acute Iron toxicity and overload?", listOf("Deferoxamine", "Dimercaprol (BAL)", "Penicillamine", "EDTA"), 0, "Deferoxamine binds free ferric iron (Fe3+) forming ferrioxamine, which is safely excreted in urine.", "Pharmacology Paper-II (Heavy Metal Antidotes)"),
            ExamQuestion(currentId++, "Pharmacology", "What heavy metal chelating agent (BAL / British Anti-Lewisite) is used to treat acute Arsenic, Mercury, and Gold poisoning?", listOf("Dimercaprol (BAL)", "Deferoxamine", "Naloxone", "Flumazenil"), 0, "Dimercaprol contains sulfhydryl groups that compete with cellular enzymes for heavy metal binding.", "Pharmacology Paper-II (Toxicology)"),
            ExamQuestion(currentId++, "Pharmacology", "Which Beta-lactamase inhibitor is combined with Amoxicillin (Augmentin) to restore activity against Beta-lactamase producing bacteria?", listOf("Clavulanic Acid (or Sulbactam / Tazobactam)", "Ciprofloxacin", "Gentamicin", "Metronidazole"), 0, "Clavulanic acid is a suicide inhibitor of bacterial Beta-lactamase enzymes, protecting Amoxicillin from enzymatic degradation.", "Pharmacology Paper-II (Penicillins & Combinations)"),
            ExamQuestion(currentId++, "Pharmacology", "Which 3rd generation Cephalosporin (Ceftriaxone) achieves excellent cerebrospinal fluid penetration and is first-line for bacterial Meningitis?", listOf("Ceftriaxone", "Cephalexin", "Cefazolin", "Cefuroxime"), 0, "Ceftriaxone crosses the inflamed blood-brain barrier effectively, covering major meningetal pathogens like N. meningitidis and S. pneumoniae.", "Pharmacology Paper-II (Cephalosporins)"),
            ExamQuestion(currentId++, "Pharmacology", "Why is Cilastatin co-administered with the carbapenem antibiotic Imipenem?", listOf("Inhibits renal dehydropeptidase-I enzyme, preventing renal breakdown of Imipenem", "Enhances oral absorption", "Prevents allergic reactions", "Blocks hepatic metabolism"), 0, "Cilastatin inhibits renal proximal tubular dehydropeptidase-I, stopping rapid inactivation of Imipenem and preventing nephrotoxic metabolites.", "Pharmacology Paper-II (Carbapenems)"),
