            ExamQuestion(currentId++, "Pharmacology", "What rapid histamine-release reaction ('Red Man Syndrome') can occur during rapid IV infusion of Vancomycin?", listOf("Systemic flushing, erythema, and hypotension caused by non-immune histamine release", "Severe acute liver necrosis", "Hemolytic anemia", "Aplastic anemia"), 0, "Rapid IV Vancomycin triggers direct mast cell histamine release, prevented by slowing infusion rate over at least 60 minutes.", "Pharmacology Paper-II (Antibiotic Adverse Reactions)"),
