            ExamQuestion(currentId++, "Pharmacology", "Which anti-tuberculosis drug inhibits mycobacterial cell wall synthesis by blocking Arabinosyl Transferase enzyme, causing Optic Neuritis?", listOf("Ethambutol", "Rifampicin", "Isoniazid", "Pyrazinamide"), 0, "Ethambutol inhibits arabinosyl transferase. Its key dose-related toxicity is retrobulbar optic neuritis causing loss of red-green color vision.", "Pharmacology Paper-II (Antitubercular Pharmacology)"),
            ExamQuestion(currentId++, "Pharmacology", "Which first-line anti-TB drug acts in acidic phagolysosomes of macrophages and causes Hyperuricemia (gouty joint pain)?", listOf("Pyrazinamide", "Isoniazid", "Rifampicin", "Ethambutol"), 0, "Pyrazinamide inhibits mycobacterial fatty acid synthase in acidic environments. It reduces renal uric acid excretion, causing hyperuricemia.", "Pharmacology Paper-II (Antitubercular Adverse Effects)"),
            ExamQuestion(currentId++, "Pharmacology", "Which polyene antifungal (Amphotericin B) binds to Ergosterol in fungal cell membranes forming pores that cause cell lysis?", listOf("Amphotericin B", "Fluconazole", "Griseofulvin", "Terbinafine"), 0, "Amphotericin B binds ergosterol, creating transmembrane pores that cause leakage of intracellular ions (K+) and fungal cell death.", "Pharmacology Paper-II (Systemic Antifungals)"),
