            ExamQuestion(currentId++, "Pharmacology", "What nucleoside analog antiviral drug (Acyclovir) is activated by viral Thymidine Kinase to inhibit Herpes Simplex DNA polymerase?", listOf("Acyclovir", "Oseltamivir", "Ribavirin", "Zidovudine"), 0, "Acyclovir monophosphate is formed by viral thymidine kinase, then converted to acyclovir triphosphate which selectively inhibits HSV DNA polymerase.", "Pharmacology Paper-II (Antiviral Pharmacology)"),
