            ExamQuestion(currentId++, "Pharmacology", "What leukotriene receptor antagonist (Montelukast) is taken orally once daily at bedtime for chronic asthma maintenance?", listOf("Montelukast", "Salbutamol", "Theophylline", "Cromolyn"), 0, "Montelukast selectively blocks CysLT1 receptors, preventing leukotriene-mediated bronchoconstriction, airway edema, and inflammation.", "Pharmacology Paper-II (Leukotriene Modulators)"),
            ExamQuestion(currentId++, "Pharmacology", "Which methylxanthine derivative (Theophylline) inhibits phosphodiesterase (PDE) enzymes and acts as an adenosine receptor antagonist?", listOf("Theophylline", "Montelukast", "Budesonide", "Tiotropium"), 0, "Theophylline increases intracellular cAMP by inhibiting PDE enzymes and antagonizes adenosine receptors, dilating bronchioles.", "Pharmacology Paper-II (Xanthine Bronchodilators)"),
            ExamQuestion(currentId++, "Pharmacology", "Which long-acting inhaled anticholinergic agent (Tiotropium) is first-line bronchodilator maintenance therapy for Chronic Obstructive Pulmonary Disease (COPD)?", listOf("Tiotropium", "Salbutamol", "Fluticasone", "Prednisolone"), 0, "Tiotropium dissociates slowly from M3 muscarinic receptors in bronchial smooth muscle, providing 24-hour bronchodilation in COPD.", "Pharmacology Paper-II (COPD Therapeutics)"),
