            ExamQuestion(currentId++, "Pharmacology", "What centrally acting synthetic opioid analgesic (Tramadol) acts as a weak mu-opioid agonist and reuptake inhibitor of Serotonin and Norepinephrine?", listOf("Tramadol", "Morphine", "Fentanyl", "Codeine"), 0, "Tramadol exerts dual analgesic mechanisms: mu-opioid receptor activation and central inhibition of norepinephrine/serotonin reuptake.", "Pharmacology Paper-II (Central Analgesics)"),
            ExamQuestion(currentId++, "Pharmacology", "Which potent systemic corticosteroid (Dexamethasone / Prednisolone) is prescribed for acute inflammatory exacerbations and severe allergic reactions?", listOf("Dexamethasone (or Prednisolone)", "Aldosterone", "Testosterone", "Insulin"), 0, "Glucocorticoids suppress phospholipase A2, reduce cytokine gene transcription, and inhibit inflammatory cell recruitment.", "Pharmacology Paper-II (Corticosteroid Therapeutics)"),
            ExamQuestion(currentId++, "Pharmacology", "Which anti-gout agent (Allopurinol) lowers serum uric acid by competitively inhibiting the enzyme Xanthine Oxidase?", listOf("Allopurinol", "Colchicine", "Probenecid", "Indomethacin"), 0, "Allopurinol and its active metabolite oxypurinol inhibit xanthine oxidase, stopping conversion of hypoxanthine and xanthine to uric acid.", "Pharmacology Paper-II (Gout Therapeutics)"),
