            ExamQuestion(currentId++, "Pharmacognosy", "Which crude drug obtained from dried rhizomes of Zingiber officinale (Family Zingiberaceae) contains gingerols and shogaols?", listOf("Ginger (Zingiber)", "Turmeric (Curcuma)", "Cardamom", "Cinnamon"), 0, "Zingiber officinale contains volatile oil and pungent oleoresin principles (Gingerols), used as antiemetic and carminative.", "Pharmacognosy Paper-II (Volatile Oils & Oleoresins)"),
            ExamQuestion(currentId++, "Pharmacognosy", "Which aromatic volatile oil rich crude drug obtained from Curcuma longa contains yellow curcuminoid polyphenols?", listOf("Turmeric (Curcuma longa)", "Ginger", "Clove", "Fennel"), 0, "Turmeric rhizomes contain Curcumin (diferuloylmethane), a yellow anti-inflammatory antioxidant polyphenol.", "Pharmacognosy Paper-II (Curcuminoids)"),
