            ExamQuestion(currentId++, "Pharmacognosy", "Which insecticidal natural crude drug powder is obtained from dried flower heads of Chrysanthemum cinerariifolium (Pyrethrum)?", listOf("Pyrethrum (Pyrethrins)", "Rotenone", "Neem", "Nicotine"), 0, "Pyrethrum flower heads contain Pyrethrins I & II, fast-acting neurotoxic contact insecticides.", "Pharmacognosy Paper-II (Natural Insecticides)"),
            ExamQuestion(currentId++, "Pharmacognosy", "What is the primary bitter isoquinoline alkaloid extracted from Hydrastis canadensis (Goldenseal) or Berberis vulgaris?", listOf("Berberine", "Morphine", "Quinine", "Atropine"), 0, "Berberine is a bright yellow protoberberine isoquinoline alkaloid with antimicrobial and antidiarrheal actions.", "Pharmacognosy Paper-II (Isoquinoline Alkaloids)"),
